"use client";

import "../../styles/whatiuse-base.css";
import "../../styles/components/data-result-summary.css";
import type { HTMLAttributes, ReactNode } from "react";
import { cn } from "../../lib/cn";

export type DataResultSummaryProps = Omit<HTMLAttributes<HTMLOutputElement>, "children"> & {
  total: number;
  filtered?: number;
  selected?: number;
  noun?: string;
  detail?: ReactNode;
};

export function DataResultSummary({ total, filtered, selected = 0, noun = "result", detail, className, ...props }: DataResultSummaryProps) {
  const shown = filtered ?? total;
  const pluralNoun = shown === 1 ? noun : `${noun}s`;
  return (
    <output className={cn("whatiuse-data-result-summary", className)} {...props}>
      <span><strong>{shown.toLocaleString()}</strong> {pluralNoun}</span>
      {filtered !== undefined && filtered !== total && <span>of {total.toLocaleString()}</span>}
      {selected > 0 && <span className="whatiuse-data-result-summary__selected">{selected.toLocaleString()} selected</span>}
      {detail && <span className="whatiuse-data-result-summary__detail">{detail}</span>}
    </output>
  );
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer whatiuse.tokens, whatiuse.base, whatiuse.components;

@layer whatiuse.components {
.whatiuse-data-result-summary {
  display: flex;
  min-width: 0;
  flex-wrap: wrap;
  align-items: center;
  gap: 3px 6px;
  color: var(--whatiuse-fg-subtle);
  font-size: var(--whatiuse-type-metadata);
  font-variant-numeric: tabular-nums;
}

.whatiuse-data-result-summary strong { color: var(--whatiuse-fg-default); font-weight: 590; }

.whatiuse-data-result-summary__selected { color: var(--whatiuse-fg-muted); }

.whatiuse-data-result-summary__detail { flex-basis: 100%; color: var(--whatiuse-fg-muted); }
}
